**The rule:** use a class when you have state that multiple functions need to share. If you keep passing the same arguments to every function (`token`, `base_url`, `session`), that's a sign it should be a class.

```python
# BAD — passing state everywhere
def get_pipelines(base_url, token, project_id):
    ...

def get_jobs(base_url, token, project_id, pipeline_id):
    ...

def post_comment(base_url, token, project_id, mr_iid, body):
    ...

# GOOD — state lives in the class
class GitLabAPI:
    def __init__(self, base_url, token):
        self.base = base_url
        self.session = requests.Session()
        self.session.headers["PRIVATE-TOKEN"] = token

    def get_pipelines(self, project_id):
        ...

    def get_jobs(self, project_id, pipeline_id):
        ...

    def post_comment(self, project_id, mr_iid, body):
        ...
```

Functions are fine for stateless operations. Classes are for objects with identity and state.

**Why:** `@dataclass` generates `__init__`, `__repr__`, `__eq__` for you. It's the modern way to create data-holding classes without boilerplate.

```python
from dataclasses import dataclass, field
from typing import Optional, List
from datetime import datetime

@dataclass
class Pod:
    name: str
    namespace: str
    status: str
    restarts: int = 0
    image: str = ""
    node: str = ""

    @property
    def is_healthy(self) -> bool:
        return self.status == "Running" and self.restarts < 5

    @property
    def needs_attention(self) -> bool:
        return self.status in ("CrashLoopBackOff", "OOMKilled", "Error") or self.restarts >= 5

    def __str__(self) -> str:
        icon = "✓" if self.is_healthy else "✗"
        return f"[{icon}] {self.namespace}/{self.name} ({self.status}, restarts={self.restarts})"


@dataclass
class ClusterReport:
    context: str
    timestamp: datetime = field(default_factory=datetime.utcnow)
    pods: List[Pod] = field(default_factory=list)

    @property
    def unhealthy_pods(self) -> List[Pod]:
        return [p for p in self.pods if p.needs_attention]

    @property
    def summary(self) -> str:
        total = len(self.pods)
        healthy = total - len(self.unhealthy_pods)
        return f"{healthy}/{total} pods healthy in {self.context}"


# Usage
pods = [
    Pod("argocd-server-abc", "argocd", "Running", restarts=0),
    Pod("my-app-xyz", "default", "CrashLoopBackOff", restarts=8),
]

report = ClusterReport(context="eks-prod-mach-x7kq", pods=pods)
print(report.summary)
for pod in report.unhealthy_pods:
    print(pod)
```

This is the most useful class pattern in DevOps scripting. Build it once, reuse everywhere.

```python
import requests
import time
import logging
from typing import Optional, Iterator

log = logging.getLogger(__name__)


class APIClient:
    """Base class for REST API clients."""

    def __init__(self, base_url: str, timeout: tuple = (5, 30)):
        self.base = base_url.rstrip("/")
        self.timeout = timeout
        self.session = requests.Session()

    def _request(self, method: str, path: str, **kwargs) -> requests.Response:
        url = f"{self.base}{path}"
        kwargs.setdefault("timeout", self.timeout)
        response = self.session.request(method, url, **kwargs)
        response.raise_for_status()
        return response

    def get(self, path: str, **params):
        return self._request("GET", path, params=params).json()

    def post(self, path: str, body: dict):
        return self._request("POST", path, json=body).json()

    def delete(self, path: str):
        self._request("DELETE", path)

    def paginate(self, path: str, page_param="page", size_param="page_size",
                 page_size=100, **params) -> Iterator[dict]:
        """Generic paginator — yields items from each page."""
        page = 1
        while True:
            items = self.get(path, **{page_param: page, size_param: page_size}, **params)
            if not items:
                break
            yield from items
            if len(items) < page_size:
                break
            page += 1


class HarborClient(APIClient):
    """Harbor registry API client."""

    def __init__(self, base_url: str, username: str, password: str):
        super().__init__(f"{base_url}/api/v2.0")
        self.session.auth = (username, password)
        self.session.headers["accept"] = "application/json"

    def list_projects(self) -> list:
        return list(self.paginate("/projects"))

    def list_artifacts(self, project: str, repository: str) -> list:
        return list(self.paginate(f"/projects/{project}/repositories/{repository}/artifacts",
                                  with_tag=True))

    def delete_artifact(self, project: str, repository: str, digest: str, dry_run=False):
        path = f"/projects/{project}/repositories/{repository}/artifacts/{digest}"
        if dry_run:
            log.info("[DRY RUN] Would delete %s/%s@%s", project, repository, digest)
            return
        self.delete(path)
        log.info("Deleted %s/%s@%s", project, repository, digest)


# Usage
harbor = HarborClient("https://harbor.example.com", "admin", "password")
for artifact in harbor.list_artifacts("my-project", "my-app"):
    tags = [t["name"] for t in (artifact.get("tags") or [])]
    print(f"{','.join(tags) or '<untagged>'} — {artifact['digest'][:16]}")
```
